def _spells_same_unit(self, unit: str, candidate: str) -> bool:
    """Whether the draft's ``unit`` is ``candidate`` written some other way.

    A draft that answers with one element of a longer reference unit, or with that
    unit plus a word of its own, is not a second unit beside the candidate: it *is*
    the candidate, written wrong. Joining the two then offers an answer that carries
    the same thing twice, which is not what the check should ask for - the recorded
    run offers "窝藏罪;窝藏、包庇" for the reference unit 窝藏、包庇, and the solver
    refuses it, correctly, losing the unit with it.

    Sharing an edge is not enough to say that: this vocabulary is full of units that
    share a head or a tail and are different units (非法种植毒品原植物 beside 非法持有
    毒品, 生产、销售伪劣产品 beside 生产、销售假药), and those are joined, not swapped.
    Only containment, and extension of the candidate or of one of its elements, count.
    """
    if unit == candidate or unit in candidate:
        return True
    if affix_extension(candidate, unit):
        return True
    return any(
        piece in unit or affix_extension(piece, unit)
        for piece in split_parts(candidate, self.inner_punctuation)
        if piece and piece != candidate and len(piece) >= 2
    )

def _answers_candidate(self, candidate: str, units: list[str]) -> bool:
    """Whether the draft already answers ``candidate``, in whatever spelling.

    The mirror of ``_spells_same_unit``: a candidate that is a piece of a unit the
    draft carries, or that unit plus a word of its own, is answered by the draft
    already - asking for it again invites the solver to break the unit it has.
    """
    for unit in units:
        if candidate == unit or candidate in unit or self._spells_same_unit(unit, candidate):
            return True
        if any(
            piece == candidate or piece in candidate
            for piece in split_parts(unit, self.inner_punctuation)
            if piece and piece != unit and len(piece) >= 2
        ):
            return True
    return False

